draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // brain
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W / 2 + 70 + 20 * Math.sin(t), H / 2 - 20 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 100, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 120);
  ctx.lineTo(W / 2, H / 2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 130);
  ctx.lineTo(W / 2 - 20, H / 2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 130);
  ctx.lineTo(W / 2 + 20, H / 2 + 120);
  ctx.stroke();

  // insight text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Insight', W / 2, H / 2 + 180 + 10 * Math.sin(t));

  ctx.restore();
}
